mapper.select:


    a.del_flag = '0'
    and a.category_id = #{categoryId}
    and a.asset_name like concat('%', #{assetName}, '%')
    and a.asset_code like concat('%', #{assetCode}, '%')

        and (a.asset_name like concat('%', #{searchValue}, '%')
             or a.asset_code like concat('%', #{searchValue}, '%')
             or c.category_name like concat('%', #{searchValue}, '%'))

    and a.barcode like concat('%', #{barcode}, '%')
    and a.brand like concat('%', #{brand}, '%')
    and a.asset_status = #{assetStatus}
    and a.audit_status = #{auditStatus}
    and c.class_type = #{classType}

order by a.asset_id desc
